function reportAccountSizes() {
  const keys = [
    "Inbox",
    "Drafts",
    "Trash",
    "SentMail",
    "Templates",
    "Junk",
    "Archive",
    "Queue",
  ];
  for (const key of keys) {
    Glean.mail.folderTotalMessages[key].set(0);
  }
  Glean.mail.folderTotalMessages.Other.set(0);
  Glean.mail.folderTotalMessages.Total.set(0);
